using Microsoft.Xrm.Sdk;
using System;
using System.ServiceModel;
namespace Plugins.Probe { public abstract class PluginBase : IPlugin { protected string PluginClassName { get; } internal PluginBase(Type pluginClassName) { PluginClassName = pluginClassName.ToString(); } public void Execute(IServiceProvider serviceProvider) { if (serviceProvider == null) throw new InvalidPluginExecutionException(nameof(serviceProvider)); var localPluginContext = new LocalPluginContext(serviceProvider); try { ExecuteDataversePlugin(localPluginContext); } catch (FaultException<OrganizationServiceFault> orgServiceFault) { throw new InvalidPluginExecutionException($"OrganizationServiceFault: {orgServiceFault.Message}", orgServiceFault); } } protected virtual void ExecuteDataversePlugin(ILocalPluginContext localPluginContext) { } }
public interface ILocalPluginContext { IOrganizationServiceFactory OrgSvcFactory { get; } IPluginExecutionContext PluginExecutionContext { get; } ITracingService TracingService { get; } }
public class LocalPluginContext : ILocalPluginContext { public IOrganizationServiceFactory OrgSvcFactory { get; } public IPluginExecutionContext PluginExecutionContext { get; } public ITracingService TracingService { get; } public LocalPluginContext(IServiceProvider serviceProvider) { OrgSvcFactory = (IOrganizationServiceFactory)serviceProvider.GetService(typeof(IOrganizationServiceFactory)); PluginExecutionContext = (IPluginExecutionContext)serviceProvider.GetService(typeof(IPluginExecutionContext)); TracingService = (ITracingService)serviceProvider.GetService(typeof(ITracingService)); } }
}
